script:
var _DEFAULT_APPS = ['erpnext', 'hrms', 'erpnext_mz', 'pos_next', 'payments'];

frappe.ui.form.on('Contract', {
	refresh: function(frm) {
		_attach_tenant_suffix(frm);
		_update_tenant_url(frm);
		_populate_default_apps(frm);
	},
	mz_tenant: function(frm) {
		_update_tenant_url(frm);
	}
});

function _attach_tenant_suffix(frm) {
	var field = frm.fields_dict['mz_tenant'];
	if (!field || !field.$input || field._mz_suffix_attached) return;
	field._mz_suffix_attached = true;

	var $input = field.$input;
	// Make the input and suffix look like a single combined widget
	$input.css({
		'border-top-right-radius': '0',
		'border-bottom-right-radius': '0',
		'border-right': 'none'
	});
	var $suffix = $('<span>', {
		text: '.erp.mozeconomia.co.mz',
		css: {
			display: 'inline-flex',
			'align-items': 'center',
			padding: '0 10px',
			background: '#f5f7fa',
			border: '1px solid #d1d8dd',
			'border-left': 'none',
			'border-radius': '0 4px 4px 0',
			'font-size': '13px',
			color: '#6c7680',
			'white-space': 'nowrap',
			'line-height': '1'
		}
	});
	$input.parent().css('display', 'flex');
	$input.after($suffix);
}

function _update_tenant_url(frm) {
	var slug = (frm.doc.mz_tenant || '').trim().toLowerCase();
	var url = slug ? slug + '.erp.mozeconomia.co.mz' : '';
	if (frm.doc.mz_tenant_url !== url) {
		frm.set_value('mz_tenant_url', url);
	}
}

function _populate_default_apps(frm) {
	// Pre-fill the apps table with defaults only when creating a brand-new document
	// that has never had any apps added to it yet.
	// Using add_child (not set_value) so that subsequent refresh calls while the
	// document is still unsaved do not overwrite the user's current selection.
	if (!frm.doc.__islocal) return;
	if ((frm.doc.mz_apps_to_install || []).length) return;
	_DEFAULT_APPS.forEach(function(app) {
		var row = frm.add_child('mz_apps_to_install', { app_name: app });
	});
	frm.refresh_field('mz_apps_to_install');
}
